<section class="account-page"><div class="account-heading"><div><p class="eyebrow">SATICI FİNANS MERKEZİ</p><h1>Kazançlarım</h1><p>Ödenmiş siparişlerden oluşan satıcı bakiyenizi takip edin.</p></div><a class="primary-link" href="<?= e(url('seller')) ?>">Satıcı paneli</a></div><div class="account-stats"><article><span>Bekleyen kazanç</span><strong><?= number_format((float)$summary['pendingEarnings'],2,',','.') ?> ₺</strong></article><article><span>Defter bakiyesi</span><strong><?= number_format((float)$ledgerBalance,2,',','.') ?> ₺</strong></article><article><span>Bekleyen / onaylı talepler</span><strong><?= number_format((float)$reservedBalance,2,',','.') ?> ₺</strong></article><article><span>Talep edilebilir</span><strong><?= number_format((float)$availableBalance,2,',','.') ?> ₺</strong></article><article><span>Ödenmiş toplam</span><strong><?= number_format((float)$summary['withdrawnTotal'],2,',','.') ?> ₺</strong></article><article><span>İade kesintileri</span><strong><?= number_format((float)$summary['refundedTotal'],2,',','.') ?> ₺</strong></article><article><span>Net platform komisyonu</span><strong><?= number_format((float)$summary['commissionNet'],2,',','.') ?> ₺</strong></article><?php if($summary['negativeBalance']>0): ?><article><span>Karşılanması gereken bakiye</span><strong><?= number_format((float)$summary['negativeBalance'],2,',','.') ?> ₺</strong></article><?php endif; ?></div><div class="account-grid"><section class="account-card"><h2>Ödeme talebi oluştur</h2><form method="post" class="account-form"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><label>Tutar (₺)<input type="number" name="amount" min="0.01" max="<?= e(number_format((float)$availableBalance,2,'.','')) ?>" step="0.01" required></label><label>Not / ödeme bilgisi<textarea name="note" rows="3" maxlength="500"></textarea></label><button type="submit" <?= $availableBalance<0.01?'disabled':'' ?>>Talep gönder</button></form><p class="muted">Talep yönetici tarafından incelenir; otomatik banka transferi yapılmaz.</p></section><section class="account-card"><h2>Ödeme taleplerim</h2><?php foreach($withdrawalRows as $w): ?><article class="ticket-item"><div class="ticket-top"><strong><?= number_format((float)$w['amount'],2,',','.') ?> ₺</strong><span class="account-status"><?= e($w['status']) ?></span></div><p><?= e($w['note']??'') ?></p></article><?php endforeach; ?><?php if(!$withdrawalRows): ?><p class="muted">Henüz ödeme talebiniz yok.</p><?php endif; ?></section></div><section class="account-card account-section"><h2>Kazanç hareketleri</h2><div class="responsive-table"><table><thead><tr><th>Tür</th><th>Sipariş / ödeme talebi</th><th>Tutar</th><th>Durum</th></tr></thead><tbody><?php foreach($ledgerRows as $l): ?><tr><td><?= e($l['entry_type']) ?></td><td><?= e($l['order_id']??($l['withdrawal_id']?'Ödeme #'.$l['withdrawal_id']:'—')) ?></td><td><?= number_format((float)$l['amount'],2,',','.') ?> ₺</td><td><?= e($l['status']) ?></td></tr><?php endforeach; ?><?php if(!$ledgerRows): ?><tr><td colspan="4">Henüz kazanç hareketi yok.</td></tr><?php endif; ?></tbody></table></div></section></section>